

UPDATE public.app_settings SET allowed_email_domains = ARRAY['wdmcs.org'], admin_emails = ARRAY['classpilot8@gmail.com'], require_admin_approval = false WHERE id = 1;

CREATE OR REPLACE FUNCTION public.grant_admin_if_verified(_user_id uuid, _email text, _confirmed timestamptz)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF _confirmed IS NOT NULL AND lower(_email) = ANY (SELECT lower(x) FROM unnest((SELECT admin_emails FROM public.app_settings WHERE id = 1)) x) THEN
  END IF;
END $$;
REVOKE EXECUTE ON FUNCTION public.grant_admin_if_verified(uuid, text, timestamptz) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.handle_user_confirmed()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NEW.email_confirmed_at IS NOT NULL AND OLD.email_confirmed_at IS NULL THEN
    PERFORM public.grant_admin_if_verified(NEW.id, NEW.email, NEW.email_confirmed_at);
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER on_auth_user_confirmed AFTER UPDATE OF email_confirmed_at ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_user_confirmed();

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$
DECLARE
  meta jsonb := coalesce(NEW.raw_user_meta_data, '{}'::jsonb);
  s public.app_settings;
  v_grade int;
  v_school uuid;
  v_check text;
  v_is_admin boolean;
  v_course text;
  v_custom text;
  v_new_course uuid;
BEGIN
  SELECT * INTO s FROM public.app_settings WHERE id = 1;
  v_is_admin := lower(NEW.email) = ANY (SELECT lower(x) FROM unnest(s.admin_emails) x);
  BEGIN v_grade := nullif(meta->>'grade','')::int; EXCEPTION WHEN others THEN v_grade := NULL; END;
  BEGIN v_school := nullif(meta->>'school_id','')::uuid; EXCEPTION WHEN others THEN v_school := NULL; END;

  IF NOT v_is_admin THEN
    v_check := public.check_signup_eligibility(NEW.email, v_grade, v_school);
    IF v_check <> 'ok' THEN
      RAISE EXCEPTION 'ELIGIBILITY: %', v_check;
    END IF;
  ELSE
    IF v_grade IS NOT NULL AND (v_grade < 7 OR v_grade > 12) THEN v_grade := NULL; END IF;
  END IF;

  VALUES (
    NEW.id,
    left(coalesce(meta->>'first_name',''), 80),
    left(coalesce(meta->>'last_name',''), 80),
    NEW.email,
    v_grade,
    v_school,
    CASE WHEN v_is_admin OR NOT s.require_admin_approval THEN 'approved' ELSE 'pending' END,
    coalesce((meta->>'guardian_consent')::boolean, false),
    nullif(left(coalesce(meta->>'guardian_email',''), 200), '')
  );

  PERFORM public.grant_admin_if_verified(NEW.id, NEW.email, NEW.email_confirmed_at);

  IF jsonb_typeof(meta->'course_ids') = 'array' THEN
    FOR v_course IN SELECT jsonb_array_elements_text(meta->'course_ids') LOOP
      BEGIN
        SELECT NEW.id, c.id FROM public.courses c
        WHERE c.id = v_course::uuid AND c.active AND NOT c.is_custom
        ON CONFLICT DO NOTHING;
      EXCEPTION WHEN others THEN NULL;
      END;
    END LOOP;
  END IF;

  IF jsonb_typeof(meta->'custom_courses') = 'array' THEN
    FOR v_custom IN SELECT jsonb_array_elements_text(meta->'custom_courses') LIMIT 10 LOOP
      IF length(trim(v_custom)) BETWEEN 2 AND 120 THEN
        VALUES (trim(v_custom), 'Other', CASE WHEN v_grade IS NULL THEN '{}'::int[] ELSE ARRAY[v_grade] END, true, NEW.id)
        RETURNING id INTO v_new_course;
      END IF;
    END LOOP;
  END IF;
  RETURN NEW;
END $fn$;

REVOKE EXECUTE ON FUNCTION public.handle_new_user() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.handle_user_confirmed() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.log_activity() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.admin_platform_stats() FROM PUBLIC, anon;
REVOKE EXECUTE ON FUNCTION public.consume_ai_quota(text) FROM PUBLIC, anon;
